export class SpreadsheetCell {
    void setValue(double value); // 未写访问说明符时，class成员默认是private
public:
    double getValue() const;     // 从此处开始为public
private:
    double m_value;              // 从此处开始为private
};

export struct SpreadsheetCell {
    void setValue(double value); // struct中未写说明符时默认为public
    double getValue() const;
private:
    double m_value;              // 显式改为private
};
